rules.cost.rego:
package main

import rego.v1

# Cost guard: warnings the approver reads before something that costs a lot is made. Nothing here denies.

creates(rc) if "create" in rc.change.actions

warn contains {"msg": "an EKS cluster costs about 73 USD a month before any nodes", "address": rc.address} if {
	some rc in input.resource_changes
	rc.type == "aws_eks_cluster"
	creates(rc)
}

warn contains {"msg": "a NAT gateway costs about 32 USD a month plus every gigabyte through it", "address": rc.address} if {
	some rc in input.resource_changes
	rc.type == "aws_nat_gateway"
	creates(rc)
}

warn contains {"msg": "a database in two zones costs twice as much", "address": rc.address} if {
	some rc in input.resource_changes
	rc.type == "aws_db_instance"
	creates(rc)
	rc.change.after.multi_az == true
}

warn contains {"msg": sprintf("%s is a large size; check it is needed", [size]), "address": rc.address} if {
	some rc in input.resource_changes
	rc.type in {"aws_db_instance", "aws_instance", "aws_elasticache_replication_group"}
	creates(rc)
	some field in ["instance_class", "instance_type", "node_type"]
	size := rc.change.after[field]
	is_string(size)
	regex.match(`\.(([4-9]|[1-9][0-9]+)xlarge|metal)`, size)
}

warn contains {"msg": "a table with provisioned capacity is paid for whether it is used or not", "address": rc.address} if {
	some rc in input.resource_changes
	rc.type == "aws_dynamodb_table"
	creates(rc)
	rc.change.after.billing_mode == "PROVISIONED"
}

warn contains {"msg": "logs kept for ever keep costing; set how many days to keep them", "address": rc.address} if {
	some rc in input.resource_changes
	rc.type == "aws_cloudwatch_log_group"
	creates(rc)
	rc.change.after.retention_in_days == 0
}
